INSERT INTO diagnosticos (codigo, familia, titulo, texto, partes_frecuentes, orden) VALUES
('FRE-01', 'FREIDORA', 'No enciende: termopila rota o reventada', 'Síntoma: el piloto no se mantiene encendido o el equipo no enciende los quemadores. Causa probable: termocupla reventada o en mal estado que no genera la señal de seguridad a la válvula de gas. Acción: retirar los quemadores, reemplazar la termocupla y verificar continuidad antes de cerrar el equipo.', '["REP-001", "REP-002"]', 1),
('FRE-02', 'FREIDORA', 'Fuga de gas en válvula de paso o manguera', 'Síntoma: olor a gas o fuga audible en la válvula de paso o en la manguera de alimentación. Causa probable: manguera deteriorada o acople sin sellador de roscas. Acción: reemplazar manguera y válvula, sellar roscas con teflon amarillo y gastop, y probar hermeticidad antes de habilitar el equipo.', '["REP-005", "REP-006", "REP-007", "REP-008", "REP-009"]', 2),
('FRE-03', 'FREIDORA', 'No sube el aceite por falta de empaque del tanque', 'Síntoma: el aceite no sube o sube muy lento durante el llenado. Causa probable: falta o deterioro del empaque del tanque de aceite, lo que impide que la bomba genere succión. Acción: instalar empaque nuevo en el tanque de aceite y verificar el funcionamiento de la bomba.', '["REP-003"]', 3),
('FRE-04', 'FREIDORA', 'Fuga de aceite por retenedor de bomba desgastado', 'Síntoma: goteo de aceite en la base de la freidora durante la filtración. Causa probable: retenedor de la bomba de aceite desgastado o fuera de su alojamiento. Acción: desmontar el cuerpo de la bomba, reemplazar el retenedor y verificar que no existan fugas tras el rearmado.', '["REP-004"]', 4),
('FRE-05', 'FREIDORA', 'Sistema de filtrado de aceite no trabaja correctamente', 'Síntoma: el sistema de filtrado de aceite no funciona con normalidad. Causa probable: desgaste del sello mecánico y de la válvula check del sistema de filtrado. Acción: reemplazar el kit de sello mecánico y la válvula check, y realizar una prueba completa de filtrado.', '["REP-014"]', 5),
('FRE-06', 'FREIDORA', 'Fuga en válvula de drenaje (drain)', 'Síntoma: fuga de aceite en la válvula de drenaje al accionar la palanca. Causa probable: desgaste del asiento o del ensamblaje de la válvula drain. Acción: desmontar la palanca y el ensamblaje de la válvula de drenaje, reemplazarlo y probar el cierre hermetico.', '["REP-010"]', 6),
('FRE-07', 'FREIDORA', 'Panel de control desprogramado, error E-41', 'Síntoma: el panel de control se desprograma y muestra el error E-41 de memoria del controlador. Causa probable: fallo interno de la tarjeta PCB del controlador. Acción: reprogramar el controlador y, si el error persiste, reemplazar la tarjeta PCB.', NULL, 7),
('FRE-08', 'FREIDORA', 'Cable o enchufe de alimentación en mal estado', 'Síntoma: el equipo no enciende o el breaker se dispara al mover el equipo. Causa probable: cable de alimentación roto o enchufe suelto que hace falso contacto con la acometida. Acción: reemplazar el tramo de cable dañado, el enchufe, y asegurar la conexión a la acometida.', '["REP-013"]', 8),
('FRE-09', 'FREIDORA', 'Quemadores no encienden por perilla o válvula unitrol sucia', 'Síntoma: los quemadores no encienden o no mantienen la posición correcta de encendido. Causa probable: perilla de la válvula unitrol desgastada o sucia, o shiglores obstruidos. Acción: limpiar shiglores y válvula unitrol, y reemplazar la perilla si no retiene la posición.', NULL, 9),
('FRE-10', 'FREIDORA', 'Blower con ruido por jaula rozando la estructura', 'Síntoma: sonido anormal en el blower del quemador. Causa probable: la jaula del blower toca la estructura o el aspa está desalineada. Acción: desmontar el blower, realinear o reemplazar el conjunto y verificar que gire libre.', '["REP-012"]', 10),
('REF-01', 'REFRIGERADOR', 'Empaque de puerta deteriorado, pierde hermeticidad', 'Síntoma: el equipo pierde temperatura y el empaque de la puerta se ve suelto o rasgado. Causa probable: empaque de puerta deteriorado por uso que rompe la hermeticidad. Acción: tomar medidas exactas de la puerta y reemplazar el empaque por uno del mismo modelo.', '["REP-016"]', 1),
('REF-02', 'REFRIGERADOR', 'Evaporador bloqueado por hielo', 'Síntoma: el equipo no llega a la temperatura correcta y hace ruido por hielo acumulado. Causa probable: evaporador bloqueado por escarcha, generalmente por empaque de puerta en mal estado que deja entrar humedad. Acción: desbloquear el evaporador y revisar el empaque de la puerta.', '["REP-016"]', 2),
('REF-03', 'REFRIGERADOR', 'Compresor no arranca por kit de arranque defectuoso', 'Síntoma: el compresor no enciende aunque el equipo tiene alimentación eléctrica. Causa probable: kit de arranque (rele y protector térmico) defectuoso que impide el arranque del motor compresor. Acción: confirmar con arranque directo, reemplazar el kit de arranque y probar funcionamiento.', '["REP-019"]', 3),
('REF-04', 'REFRIGERADOR', 'Controlador electrónico dañado', 'Síntoma: el equipo presenta condensación en el evaporador y no mantiene la temperatura configurada. Causa probable: daño electrónico en el controlador digital (full gauge). Acción: desbloquear el evaporador y reemplazar el controlador digital dañado.', '["REP-018"]', 4),
('REF-05', 'REFRIGERADOR', 'Clips de estante rotos o faltantes', 'Síntoma: los estantes internos no se sujetan correctamente. Causa probable: clips plásticos de sujeción de estantes rotos o faltantes por desgaste. Acción: reemplazar los clips plásticos por repuestos originales del fabricante.', '["REP-020"]', 5),
('REF-06', 'REFRIGERADOR', 'Fuga de gas refrigerante en presostato', 'Síntoma: el equipo no llega a temperatura pese a que el motor ventilador funciona con normalidad. Causa probable: fuga de gas refrigerante localizada en el presostato de alta o baja presión. Acción: localizar la fuga, reemplazar el presostato, cargar gas y probar presiones de trabajo.', '["REP-021"]', 6),
('REF-07', 'REFRIGERADOR', 'Sonido fuerte por hielo golpeando el ventilador interno', 'Síntoma: sonido fuerte dentro del equipo. Causa probable: el ventilador interno golpea una capa de hielo generada por bloqueo del evaporador. Acción: desbloquear el hielo acumulado, verificar giro libre del ventilador y revisar el empaque de la puerta.', '["REP-016"]', 7),
('REF-08', 'REFRIGERADOR', 'Pernos de base de ventiladores de cuarto frío flojos', 'Síntoma: vibración y ruido en los ventiladores del cuarto frío. Causa probable: pernos de la base de los motores ventiladores flojos por vibración continua. Acción: colocar rodelas con aislante y ajustar pernos y tuercas de la base.', NULL, 8),
('REF-09', 'REFRIGERADOR', 'Cortinas de cuarto frío deterioradas', 'Síntoma: perdida de frío al ingresar al cuarto frío. Causa probable: cortinas plasticas de la puerta del cuarto frío rotas o deterioradas por el uso. Acción: medir el vano de la puerta e instalar cortinas nuevas del ancho y largo correspondiente.', '["REP-023"]', 9),
('REF-10', 'REFRIGERADOR', 'Compresor con bobinas aterrizadas', 'Síntoma: el compresor no enciende y el breaker se dispara. Causa probable: bobinas internas del compresor aterrizadas por falla eléctrica interna. Acción: confirmar el aterrizaje con megado, reemplazar el compresor según placa del equipo y realizar vacío del sistema.', '["REP-017"]', 10),
('HIE-01', 'MAQUINA DE HIELO', 'Hielo amarillo por sarro o calcificación', 'Síntoma: el hielo sale amarillento y con sabor extraño. Causa probable: acumulación de sarro (calcio) en flautas, bandeja y tuberías de distribución de agua. Acción: realizar limpieza y descalcificación completa con el kit correspondiente y sanitizar el equipo.', '["REP-025", "REP-026", "REP-029"]', 1),
('HIE-02', 'MAQUINA DE HIELO', 'Sensor de nivel o de grosor de hielo dañado', 'Síntoma: el equipo no produce hielo o detiene la producción de forma anomala. Causa probable: sensor de nivel de agua o de grosor de hielo dañado o sucio. Acción: limpiar los pines del sensor y, si no recupera continuidad, reemplazar el sensor de nivel de agua.', '["REP-027", "REP-028"]', 2),
('HIE-03', 'MAQUINA DE HIELO', 'Panel touch no enciende ni responde', 'Síntoma: el panel táctil no enciende y el equipo no produce hielo. Causa probable: falla del panel touch o de su continuidad interna según el manual del fabricante. Acción: verificar continuidad del panel táctil y reemplazar el conjunto de marco y panel digital.', '["REP-030"]', 3),
('HIE-04', 'MAQUINA DE HIELO', 'Filtración de agua en bandeja de subenfriamiento', 'Síntoma: fuga de agua en la bandeja de subenfriamiento del equipo. Causa probable: sellos o uniones de la bandeja deteriorados. Acción: sellar la fuga con material asfaltico autoadhesivo y verificar que no se repita tras la sanitización.', NULL, 4),
('HIE-05', 'MAQUINA DE HIELO', 'Falla en sensor de agua o boya del bin', 'Síntoma: el equipo bota solo agua o la bandeja de recolección se llena sin producir hielo. Causa probable: sonda o boya de nivel de agua sucia u obstruida por sarro. Acción: limpiar la sonda de agua y las boyas, y reemplazar si no recupera la señal.', '["REP-027"]', 5),
('HIE-06', 'MAQUINA DE HIELO', 'Fuga de agua por manguera de desague doblada', 'Síntoma: el equipo derrama agua por la parte trasera. Causa probable: manguera de desague doblada u obstruida que impide el drenaje correcto. Acción: enderezar o reemplazar la manguera de desague y verificar el flujo de drenaje.', NULL, 6),
('HIE-07', 'MAQUINA DE HIELO', 'Válvula solenoide de agua defectuosa', 'Síntoma: el equipo no llena agua correctamente para el ciclo de fabricación. Causa probable: válvula solenoide de entrada de agua de 120V defectuosa. Acción: reemplazar la válvula solenoide y verificar el ciclo completo de llenado.', '["REP-031"]', 7),
('HIE-08', 'MAQUINA DE HIELO', 'Compresor sin compresión o fuga de refrigerante', 'Síntoma: el equipo no enfria ni produce hielo. Causa probable: fuga de gas refrigerante R410A o compresor sin compresión. Acción: localizar la fuga, reparar, cargar refrigerante con el kit de suelda y varillas, y verificar presiones de trabajo.', '["REP-033"]', 8),
('HIE-09', 'MAQUINA DE HIELO', 'Tarjeta electrónica de control dañada', 'Síntoma: el equipo no enciende o no completa el ciclo de fabricación de hielo. Causa probable: daño en la tarjeta electrónica de control. Acción: verificar voltajes de entrada y salida en la tarjeta y reemplazarla si no responde a los parametros del manual.', NULL, 9),
('CON-01', 'CONGELADOR', 'Empaque de puerta deteriorado', 'Síntoma: el congelador no llega a temperatura y presenta escarcha. Causa probable: empaque de puerta en mal estado que rompe la hermeticidad. Acción: tomar medidas y reemplazar el empaque por el modelo correspondiente.', '["REP-034"]', 1),
('CON-02', 'CONGELADOR', 'Compresor con bobinas aterrizadas o dañado', 'Síntoma: el compresor no enciende y provoca disparo del breaker. Causa probable: bobinas internas del compresor aterrizadas o compresor dañado. Acción: confirmar con megado, reemplazar el compresor según placa del equipo, y realizar vacío y carga de refrigerante.', '["REP-035", "REP-037"]', 2),
('CON-03', 'CONGELADOR', 'Motor ventilador de condensadora dañado', 'Síntoma: el equipo no llega a temperatura y el ventilador de la unidad condensadora gira despacio o no gira. Causa probable: motor ventilador dañado o recalentado. Acción: reemplazar el motor ventilador y verificar el giro libre del aspa.', '["REP-036"]', 3),
('CON-04', 'CONGELADOR', 'Cortocircuito en enchufe o toma por variación de voltaje', 'Síntoma: el equipo no enciende tras una variación de voltaje. Causa probable: cortocircuito en el enchufe o el toma de corriente por sobretensión. Acción: reemplazar enchufe y toma corriente, y recomendar la instalación de un protector de voltaje.', NULL, 4),
('CON-05', 'CONGELADOR', 'Controlador digital sin señal (full gauge)', 'Síntoma: el equipo no llega a temperatura y el controlador digital no recibe señal. Causa probable: falla del controlador full gauge o de su sonda asociada. Acción: verificar la sonda y reemplazar el controlador full gauge TC-900.', '["REP-038"]', 5),
('CON-06', 'CONGELADOR', 'Kit de arranque y pines de compresor en mal estado', 'Síntoma: el equipo no llega a temperatura y el compresor no arranca. Causa probable: kit de arranque (capacitor y rele) y pines del compresor desgastados. Acción: reemplazar el kit de arranque CSR y limpiar o reemplazar los pines de conexión del compresor.', '["REP-039"]', 6),
('CON-07', 'CONGELADOR', 'Puerta sin empaque bloquea el evaporador con hielo', 'Síntoma: el evaporador se bloquea con hielo y el equipo no llega a temperatura. Causa probable: puerta sin empaque que permite el ingreso de humedad al gabinete. Acción: desbloquear el evaporador e instalar empaque nuevo en la puerta.', '["REP-034"]', 7),
('CON-08', 'CONGELADOR', 'Recalentamiento del motor-compresor', 'Síntoma: el motor-compresor se recalienta y no funciona correctamente. Causa probable: amperaje elevado por sobrecarga o kit de arranque defectuoso. Acción: verificar amperaje contra placa, y reemplazar kit de arranque y capacitores si el consumo es mayor al nominal.', '["REP-039"]', 8),
('HOL-01', 'HOLDING CABINET', 'Empaque de puerta en mal estado', 'Síntoma: el holding cabinet pierde temperatura por las puertas. Causa probable: empaque de puerta desgastado o roto que rompe la hermeticidad del gabinete. Acción: medir y reemplazar el empaque de puerta según el modelo HC-900 o HC-903.', '["REP-041"]', 1),
('HOL-02', 'HOLDING CABINET', 'Switch de encendido en corto', 'Síntoma: el equipo no enciende o presenta cortocircuito al accionar el switch. Causa probable: switch interruptor conmutador dañado internamente. Acción: reemplazar el switch de encendido y verificar el circuito de alimentación.', '["REP-040"]', 2),
('HOL-03', 'HOLDING CABINET', 'Resistencia explotada internamente', 'Síntoma: el equipo no llega a la temperatura de retención requerida. Causa probable: resistencia interna explotada o sin continuidad. Acción: medir la resistencia con multimetro, reemplazarla, instalar y verificar funcionamiento.', '["REP-043"]', 3),
('HOL-04', 'HOLDING CABINET', 'Motor ventilador con bobinas recalentadas', 'Síntoma: el motor ventilador no funciona o hace ruido y el equipo no llega a temperatura. Causa probable: bobinas del motor ventilador recalentadas por desgaste de rodamientos. Acción: limpiar y lubricar de forma provisional, y reemplazar el motor ventilador con su lana de fibra cerámica.', '["REP-042"]', 4),
('HOL-05', 'HOLDING CABINET', 'Lana cerámica de aislamiento deteriorada', 'Síntoma: el equipo no retiene la temperatura interna de forma uniforme. Causa probable: lana de fibra cerámica de aislamiento térmico deteriorada. Acción: retirar la lana antigua y colocar lana cerámica nueva en la cavidad del gabinete.', '["REP-042"]', 5),
('HOL-06', 'HOLDING CABINET', 'Clavija de alimentación derretida', 'Síntoma: el equipo no enciende. Causa probable: clavija de alimentación derretida que impide un buen contacto con el tomacorriente. Acción: reemplazar la clavija y el cable de alimentación de 12 AWG.', '["REP-045"]', 6),
('HOL-07', 'HOLDING CABINET', 'Sonda de temperatura RTD dañada (errores E4 o E6)', 'Síntoma: el panel muestra errores de sobrecalentamiento o de sonda de temperatura. Causa probable: sonda de temperatura RTD dañada o mal conectada. Acción: reemplazar la sonda RTD y verificar la lectura en el panel de control.', '["REP-044"]', 7),
('HOL-08', 'HOLDING CABINET', 'Cableado de alimentación deteriorado', 'Síntoma: el equipo presenta fallas intermitentes de encendido. Causa probable: cableado de alimentación deteriorado por el uso y el calor del gabinete. Acción: reemplazar el cable de alimentación de 12 AWG completo con sus tres conductores.', '["REP-045"]', 8),
('HOR-01', 'HORNO', 'Fugas de flama en quemadores por cerámicas rotas', 'Síntoma: fugas de flama hacia arriba y lenguetas de fuego en los quemadores. Causa probable: cerámicas de los quemadores rotas o mallas fisuradas. Acción: desmontar los quemadores, reemplazar cerámicas y mallas, y calibrar la flama.', '["REP-048"]', 1),
('HOR-02', 'HORNO', 'Malla de quemador fisurada (contra explosiones)', 'Síntoma: contra explosiones al encender los quemadores. Causa probable: mallas de los quemadores fisuradas que dejan pasar exceso de gas antes de encender. Acción: reemplazar las mallas y colocar lana de vidrio en el quemador afectado.', '["REP-048"]', 2),
('HOR-03', 'HORNO', 'Manguera de gas inadecuada o sin ataque rápido', 'Síntoma: riesgo de fuga en la acometida de gas del horno. Causa probable: manguera de gas no apta o sin ataque rápido instalado. Acción: instalar manguera con ataque rápido del diámetro correcto y sellar con teflon amarillo.', '["REP-047"]', 3),
('HOR-04', 'HORNO', 'Tornillos de sujeción de quemadores oxidados', 'Síntoma: los quemadores presentan holgura o desalineación. Causa probable: tornillos de sujeción oxidados que pierden torque. Acción: reemplazar los tornillos por repuestos originales y ajustar el conjunto de quemadores.', '["REP-049"]', 4),
('HOR-05', 'HORNO', 'Shiglores sucios con acumulación de grasa', 'Síntoma: los quemadores no tienen fuerza de llama. Causa probable: shiglores y tubería de cobre con acumulación de grasa que restringe el paso de gas. Acción: desmontar y limpiar el conjunto de shiglores y la tubería de cobre.', '["REP-052"]', 5),
('HOR-06', 'HORNO', 'Válvula de gas en mal estado', 'Síntoma: los quemadores no encienden con fuerza uniforme. Causa probable: válvula de gas del horno en mal estado o con fuga interna. Acción: reemplazar la válvula de gas y verificar la presión de trabajo.', '["REP-051"]', 6),
('HOR-07', 'HORNO', 'Switch de paso de gas dañado (no enciende)', 'Síntoma: el horno no enciende. Causa probable: switch eléctrico de paso de gas dañado. Acción: corregir la anomalia de forma provisional y reemplazar el switch de paso de gas de manera urgente.', NULL, 7),
('HOR-08', 'HORNO', 'Empaque de puerta roto', 'Síntoma: perdida de calor por la puerta del horno. Causa probable: empaque principal de la puerta roto o desprendido. Acción: reemplazar el empaque de puerta y verificar el cierre hermetico.', NULL, 8),
('HOR-09', 'HORNO', 'Magnetrón dañado en horno tipo turbo (error F3)', 'Síntoma: error F3 relacionado al circuito del magnetrón. Causa probable: magnetrón dañado o antena de microondas desgastada. Acción: reemplazar el kit de servicio del magnetrón y el filtro de aire, y limpiar los ventiladores.', NULL, 9),
('MRF-01', 'MESA REFRIGERADA', 'Empaque de puerta o cajón deteriorado', 'Síntoma: la mesa refrigerada pierde temperatura. Causa probable: empaque de puerta o de cajonera deteriorado o faltante. Acción: tomar medidas exactas y reemplazar el empaque según el modelo de la mesa.', '["REP-053"]', 1),
('MRF-02', 'MESA REFRIGERADA', 'Junta de cajón en mal estado', 'Síntoma: perdida de frío en el compartimento de cajones. Causa probable: junta de cajón desgastada que no sella correctamente. Acción: reemplazar la junta de cajón y verificar el cierre hermetico.', '["REP-054"]', 2),
('MRF-03', 'MESA REFRIGERADA', 'Breaker matic saltado, el equipo no enciende', 'Síntoma: el equipo no enciende o no llega a temperatura. Causa probable: breaker matic de protección saltado por sobrecarga o falla de aislamiento. Acción: revisar el circuito, corregir la falla y reemplazar el breaker matic si no restablece.', '["REP-055"]', 3),
('MRF-04', 'MESA REFRIGERADA', 'Riel de cajón desgastado (el cajón no cierra)', 'Síntoma: el cajón no abre ni cierra correctamente. Causa probable: riel de cajón salido de su posición y ruedas desgastadas. Acción: reemplazar el riel bajo modelo y ajustar su alineación.', NULL, 4),
('MRF-05', 'MESA REFRIGERADA', 'Compresor sin refrigeración', 'Síntoma: la mesa refrigerada no baja de temperatura. Causa probable: compresor sin compresión o fuga de gas refrigerante R134a. Acción: reemplazar el compresor y el filtro deshidratador, y cargar refrigerante según el sistema.', '["REP-056"]', 5),
('MRF-06', 'MESA REFRIGERADA', 'Motor ventilador trasero con obstrucción', 'Síntoma: sonido extraño en la parte trasera del equipo. Causa probable: motor ventilador trasero obstruido o desalineado. Acción: acomodar o reemplazar el motor ventilador y verificar el giro libre.', NULL, 6),
('MRF-07', 'MESA REFRIGERADA', 'Kit de arranque en mal estado (no baja temperatura)', 'Síntoma: el equipo no baja de temperatura. Causa probable: kit de arranque del compresor en mal estado con bobinas desfasadas. Acción: reemplazar el kit de arranque y realizar prueba de amperaje del compresor.', NULL, 7),
('MRF-08', 'MESA REFRIGERADA', 'Parante de puertas desalineado', 'Síntoma: el equipo no llega a la temperatura requerida. Causa probable: parante que une las puertas fuera de posición, rompiendo la hermeticidad. Acción: realinear el parante y verificar el sello de las puertas.', NULL, 8),
('LIC-01', 'LICUADORA', 'Clutch desgastado (sonido fuerte, no gira)', 'Síntoma: sonido fuerte al encender o la licuadora no gira el vaso. Causa probable: clutch de acople desgastado por uso intensivo. Acción: reemplazar el clutch y probar el acople con el vaso.', '["REP-057"]', 1),
('LIC-02', 'LICUADORA', 'Cuchillas desgastadas (licua lento)', 'Síntoma: la licuadora tarda demasiado en licuar o licua de forma irregular. Causa probable: conjunto de cuchillas desgastado. Acción: reemplazar el conjunto de cuchillas Advance y probar el ciclo de licuado.', '["REP-058"]', 2),
('LIC-03', 'LICUADORA', 'Conjunto de vaso de accionamiento desgastado', 'Síntoma: la licuadora no transmite el giro correctamente al vaso. Causa probable: conjunto de vaso de accionamiento (drive socket) desgastado. Acción: reemplazar el conjunto de accionamiento y verificar el acople con el clutch.', '["REP-059"]', 3),
('LIC-04', 'LICUADORA', 'Junta de aislamiento deteriorada (fuga por la base)', 'Síntoma: fuga de liquido por la base del vaso. Causa probable: junta de aislamiento en mal estado. Acción: reemplazar la junta de aislamiento y probar la hermeticidad del vaso.', '["REP-060"]', 4),
('LIC-05', 'LICUADORA', 'Carbones de motor desgastados', 'Síntoma: el motor pierde fuerza o no gira con normalidad. Causa probable: carbones de motor desgastados por uso prolongado. Acción: reemplazar los carbones de motor y verificar el consumo eléctrico.', '["REP-061"]', 5),
('LIC-06', 'LICUADORA', 'Cables pelados en el sistema eléctrico interno', 'Síntoma: la licuadora se acciona sola o de forma intermitente. Causa probable: cables internos pelados que generan falso contacto. Acción: reemplazar el tramo de cable dañado y aislar las conexiones internas.', NULL, 6),
('LIC-07', 'LICUADORA', 'Tarjeta de control con daño por humedad', 'Síntoma: la licuadora no enciende o no responde al panel de control. Causa probable: agua ingresada a la tarjeta de control que genera corrosión en las pistas. Acción: limpiar la tarjeta, verificar continuidad y reemplazarla si no recupera funcionamiento.', NULL, 7),
('LIC-08', 'LICUADORA', 'Engranes o pinon de vaso desgastados', 'Síntoma: la licuadora hace ruido fuerte y no trabaja correctamente. Causa probable: pinon de engrane del vaso desgastado junto con el clutch. Acción: reemplazar el clutch y el pinon de engrane desgastado.', '["REP-057"]', 8),
('CAF-01', 'MAQUINA DE CAFE', 'Goteo en ducha por empaque cristalizado', 'Síntoma: goteo constante en la ducha del grupo de cafe. Causa probable: junta de grupo (gasket) cristalizada por el calor y el uso. Acción: reemplazar la junta de grupo y probar la extracción.', '["REP-062"]', 1),
('CAF-02', 'MAQUINA DE CAFE', 'Switch de encendido dañado (no enciende)', 'Síntoma: la cafetera no enciende. Causa probable: switch de encendido de 4 pines en mal estado internamente. Acción: reemplazar el switch de encendido y verificar el ingreso de voltaje.', '["REP-063"]', 2),
('CAF-03', 'MAQUINA DE CAFE', 'Sensor de temperatura de caldera defectuoso', 'Síntoma: el equipo mantiene la temperatura pero no calienta correctamente el cafe. Causa probable: sensor interno de temperatura de la caldera dañado. Acción: reemplazar el sensor de temperatura y verificar el amperaje de la resistencia.', '["REP-065"]', 3),
('CAF-04', 'MAQUINA DE CAFE', 'Válvula de alivio de presión defectuosa', 'Síntoma: presión irregular en la caldera de la cafetera. Causa probable: válvula de alivio de presión defectuosa o mal calibrada. Acción: reemplazar la válvula de alivio y verificar la presión de trabajo de la caldera.', '["REP-064"]', 4),
('CAF-05', 'MAQUINA DE CAFE', 'Electroválvula solenoide de agua defectuosa', 'Síntoma: filtración de agua por el sistema de ducha. Causa probable: electroválvula solenoide de agua en mal estado. Acción: reemplazar la electroválvula solenoide y probar el ciclo de agua caliente.', '["REP-066"]', 5),
('CAF-06', 'MAQUINA DE CAFE', 'Contramuelle roto (palanca de grupo)', 'Síntoma: la palanca del grupo no retorna correctamente. Causa probable: contramuelle de la cimbra roto. Acción: reemplazar el contramuelle y verificar el mecanismo de la palanca.', NULL, 6),
('CAF-07', 'MAQUINA DE CAFE', 'Motor de molino trabado por cafe solidificado', 'Síntoma: el molino no muele el cafe. Causa probable: motor del molino trabado por acumulación de cafe solidificado. Acción: desmontar y limpiar el mecanismo del molino, y verificar el giro libre del motor.', NULL, 7),
('CAF-08', 'MAQUINA DE CAFE', 'Calcificación interna, requiere descalcificación', 'Síntoma: empaques cristalizados y bajo rendimiento en la extracción. Causa probable: acumulación de sarro por falta de descalcificación periodica. Acción: aplicar descalcificante según el manual y reemplazar los empaques cristalizados.', '["REP-067", "REP-062"]', 8),
('HEL-01', 'MAQUINA DE HELADO', 'Espárrago o perno de mascarilla suelto', 'Síntoma: el equipo trabaja de forma ineficiente por ingreso de aire. Causa probable: espárrago o perno de sujeción de la mascarilla suelto o a punto de ruptura. Acción: reemplazar el espárrago o los pernos y ajustar la mascarilla.', '["REP-068", "REP-069"]', 1),
('HEL-02', 'MAQUINA DE HELADO', 'Fuga de refrigerante en el compresor', 'Síntoma: el equipo no llega a temperatura en las tolvas. Causa probable: fuga de gas refrigerante que reduce la capacidad del compresor. Acción: localizar la fuga, reparar, cargar refrigerante y verificar la presión de trabajo.', '["REP-070", "REP-071"]', 2),
('HEL-03', 'MAQUINA DE HELADO', 'Tarjeta de mando no desactiva el compresor', 'Síntoma: el producto se congela en exceso dentro de la tolva. Causa probable: tarjeta de mando que no desactiva el compresor en el punto de consistencia correcto. Acción: verificar los parametros de viscosidad y temperatura, y reemplazar la tarjeta si no responde.', NULL, 3),
('HEL-04', 'MAQUINA DE HELADO', 'Motor de bomba de circulación no arranca', 'Síntoma: el equipo no hace circular la mezcla en la tolva. Causa probable: motor de la bomba de circulación que no entra en funcionamiento. Acción: verificar con el botón de comprobación y reemplazar el motor de la bomba si no arranca.', NULL, 4),
('HEL-05', 'MAQUINA DE HELADO', 'Bandas de transmisión desgastadas (olor a quemado)', 'Síntoma: olor a quemado durante la operación del equipo. Causa probable: bandas de transmisión desgastadas por fricción excesiva. Acción: reemplazar las bandas de transmisión y verificar la tension de la polea.', NULL, 5),
('HEL-06', 'MAQUINA DE HELADO', 'Protector térmico del motor activado', 'Síntoma: error en pantalla y el equipo se detiene. Causa probable: protector térmico del motor activado por sobrecarga, con contacto dañado. Acción: reiniciar el protector, reemplazar el contacto dañado y verificar el consumo del motor.', NULL, 6),
('HEL-07', 'MAQUINA DE HELADO', 'Empaque de baston mixto roto (filtración entre tolvas)', 'Síntoma: filtración de mezcla de una tolva hacia la otra. Causa probable: empaque del baston mixto roto o desgastado. Acción: reemplazar el empaque del baston mixto y probar el sellado entre tolvas.', NULL, 7),
('HEL-08', 'MAQUINA DE HELADO', 'Puerta de vidrio rota', 'Síntoma: la puerta de exhibicion del equipo presenta rotura del vidrio. Causa probable: golpe o fatiga del vidrio templado de la puerta. Acción: tomar las medidas de la puerta y reemplazar el vidrio completo.', NULL, 8),
('COC-01', 'COCINA', 'Fuga de gas en tubería o rubinete', 'Síntoma: olor a gas en la cocina industrial. Causa probable: tubería de cobre en mal estado o rubinete con fuga por desgaste. Acción: reemplazar el tramo de tubería, anillos y tuercas de compresión, y verificar hermeticidad con agua jabonosa.', '["REP-073", "REP-074", "REP-075", "REP-077"]', 1),
('COC-02', 'COCINA', 'Quemadores sin fuerza por shiglores obstruidos', 'Síntoma: los quemadores no salen con fuerza y ennegrecen las ollas. Causa probable: shiglores obstruidos u oxigenadores mal regulados. Acción: limpiar o reemplazar los shiglores y regular los oxigenadores de cada quemador.', '["REP-076"]', 2),
('COC-03', 'COCINA', 'Manguera de gas sin válvula reguladora', 'Síntoma: riesgo de fuga en la acometida de gas de la cocina. Causa probable: manguera de gas sin válvula reguladora ni ataque rápido instalados. Acción: instalar manguera con ataque rápido y válvula reguladora, y sellar con teflon.', NULL, 3),
('COC-04', 'COCINA', 'Piloto en mal estado (llama amarilla, hollin)', 'Síntoma: llama amarillenta y presencia de hollin en las ollas. Causa probable: piloto en mal estado o mal ubicado que genera combustion incompleta. Acción: reemplazar el piloto, reubicarlo correctamente y calibrar la llama.', NULL, 4),
('COC-05', 'COCINA', 'Panel de control con error de sonda (PROBE)', 'Síntoma: el panel muestra error de sonda (PROBE) y el equipo se deshabilita. Causa probable: sonda de temperatura dañada o mal conectada. Acción: verificar la sonda y su conexión, y reemplazarla si el error persiste tras las pruebas.', NULL, 5),
('COC-06', 'COCINA', 'Tornillos de sujeción de estructura oxidados', 'Síntoma: la estructura de la cocina presenta holgura o riesgo de ruptura. Causa probable: tornillos de sujeción oxidados por el ambiente humedo de la cocina. Acción: reemplazar los tornillos y reforzar la sujeción de la estructura.', NULL, 6),
('COC-07', 'COCINA', 'Bobina de inducción abierta (no calienta)', 'Síntoma: la cocina de inducción no calienta. Causa probable: bobina de inducción abierta o tarjeta electrónica en corto. Acción: verificar la continuidad de la bobina y reemplazar la tarjeta electrónica si está dañada.', NULL, 7),
('COC-08', 'COCINA', 'Rubinete de piloto con fuga', 'Síntoma: fuga de gas en el sistema de piloto de la cocina. Causa probable: rubinete del piloto desgastado o con roscas dañadas. Acción: reemplazar el rubinete del piloto y sellar con teflon amarillo.', '["REP-077"]', 8),
('PLA-01', 'PLANCHA', 'Fuga de gas en válvula o acople de tubería', 'Síntoma: fuga de gas cerca del acople de la válvula de la plancha o parrilla. Causa probable: válvula de gas suelta del acople o tuerca barrida. Acción: reemplazar la válvula de gas y el acople, y sellar con teflon amarillo.', '["REP-078"]', 1),
('PLA-02', 'PLANCHA', 'Rubinetes desgastados (llama baja o eje trabado)', 'Síntoma: llama baja o irregular en uno o varios quemadores. Causa probable: rubinetes con eje trabado o desgastado por el uso. Acción: reemplazar los rubinetes afectados y calibrar la llama de cada quemador.', '["REP-078"]', 2),
('PLA-03', 'PLANCHA', 'Perillas de control desgastadas', 'Síntoma: dificultad para regular la llama desde las perillas. Causa probable: perillas de control desgastadas que no acoplan bien al rubinete. Acción: reemplazar las perillas de control en acero inoxidable.', '["REP-079"]', 3),
('PLA-04', 'PLANCHA', 'Hi limit dañado (no enciende)', 'Síntoma: la plancha no enciende. Causa probable: hi limit (termostato de seguridad) dañado que corta la alimentación. Acción: conectar de forma provisional en directo y reemplazar el hi limit de manera urgente.', NULL, 4),
('PLA-05', 'PLANCHA', 'Empaque de cajonera de base deteriorado', 'Síntoma: la base de la plancha con cajonera pierde temperatura. Causa probable: empaque inferior de la cajonera deteriorado o faltante. Acción: medir y reemplazar el empaque inferior de la cajonera.', '["REP-080"]', 5),
('PLA-06', 'PLANCHA', 'Quemador roto o fisurado', 'Síntoma: uno de los quemadores no enciende o tiene llama irregular. Causa probable: quemador roto o fisurado por fatiga del material. Acción: reemplazar el quemador dañado y calibrar la llama del conjunto.', NULL, 6),
('PLA-07', 'PLANCHA', 'Válvula termostatica de quemador central sin apagar', 'Síntoma: el quemador central se queda encendido y no apaga. Causa probable: mecanismo de apertura y cierre de la válvula termostatica dañado. Acción: reemplazar la válvula termostatica del quemador central.', NULL, 7),
('PLA-08', 'PLANCHA', 'Polas de nivel desajustadas (plancha desnivelada)', 'Síntoma: la plancha queda desnivelada al abrirla. Causa probable: polas de nivel mal calibradas en el mecanismo de apertura. Acción: calibrar las polas de nivel y verificar el nivel de la superficie de cocción.', NULL, 8),
('MCA-01', 'MESA CALIENTE', 'Clavija o enchufe recalentado, equipo sin funcionar', 'Síntoma: el equipo deja de funcionar y el cuerpo de la clavija está recalentado. Causa probable: clavija de alimentación quemada por falso contacto o sobrecarga. Acción: reemplazar la clavija empotrada completa y revisar el punto de conexión.', '["REP-083"]', 1),
('MCA-02', 'MESA CALIENTE', 'Resistencia explotada (no calienta)', 'Síntoma: la mesa caliente no calienta o se apaga sola. Causa probable: resistencia tipo M explotada o con terminales sulfatados. Acción: reemplazar la resistencia tipo M y los terminales de conexión afectados.', '["REP-082"]', 2),
('MCA-03', 'MESA CALIENTE', 'Terminales de resistencia sulfatados por agua', 'Síntoma: la mesa caliente no llega a temperatura. Causa probable: terminales de la resistencia sulfatados por contacto con agua o liquidos. Acción: limpiar o reemplazar los terminales sulfatados y aislar la conexión.', NULL, 3),
('MCA-04', 'MESA CALIENTE', 'Control digital dañado por humedad', 'Síntoma: el equipo no enciende y el control digital no responde. Causa probable: elementos electrónicos del control digital sulfatados por contacto con agua. Acción: reemplazar el control digital y proteger la conexión contra salpicaduras.', NULL, 4),
('MCA-05', 'MESA CALIENTE', 'Sonda de control dañada', 'Síntoma: la mesa caliente no regula bien la temperatura. Causa probable: sonda del control digital (full gauge) dañada. Acción: reemplazar la sonda del control y calibrar la temperatura de trabajo.', '["REP-085"]', 5),
('MCA-06', 'MESA CALIENTE', 'Termostato defectuoso', 'Síntoma: la mesa caliente se sobrecalienta o no corta la temperatura. Causa probable: termostato en mal estado. Acción: reemplazar el termostato de 0 a 90 grados y probar el corte de temperatura.', '["REP-084"]', 6),
('MCA-07', 'MESA CALIENTE', 'Switch de poder con pines rotos', 'Síntoma: el equipo no enciende. Causa probable: switch de poder con pines rotos o sobrecalentados. Acción: reemplazar el switch de poder y revisar el circuito de alimentación.', NULL, 7),
('MCA-08', 'MESA CALIENTE', 'Cables expuestos por manguera bx deteriorada', 'Síntoma: riesgo eléctrico por cables expuestos junto a la mesa caliente. Causa probable: manguera bx de protección de cables deteriorada o faltante. Acción: instalar manguera bx nueva para recubrir los cables expuestos.', NULL, 8),
('ARR-01', 'OLLA ARROCERA', 'Piloto o flauta con fuga de gas', 'Síntoma: fuga de gas en el sistema de piloto de la olla arrocera. Causa probable: piloto o flauta deteriorados por el uso continuo. Acción: reemplazar el tubo piloto y el porta electrodo, y verificar la hermeticidad.', '["REP-086"]', 1),
('ARR-02', 'OLLA ARROCERA', 'Olla interna desgastada (el arroz se pega)', 'Síntoma: el arroz se pega dentro de la olla. Causa probable: desgaste del recubrimiento interno de la olla. Acción: evaluar el estado de la olla interna y reemplazarla si el desgaste es irreversible.', '["REP-089"]', 2),
('ARR-03', 'OLLA ARROCERA', 'Pata de la olla rota (inestabilidad)', 'Síntoma: la olla arrocera se encuentra inestable. Causa probable: una de las patas de apoyo rota o fisurada. Acción: reemplazar la pata dañada y verificar la nivelación del equipo.', '["REP-087"]', 3),
('ARR-04', 'OLLA ARROCERA', 'Ciclor de paso de gas obstruido o dañado', 'Síntoma: el gas no pasa correctamente hacia el quemador de la olla. Causa probable: ciclor recto del sistema de paso de gas obstruido o dañado. Acción: reemplazar el ciclor recto y verificar el flujo de gas.', '["REP-088"]', 4),
('ARR-05', 'OLLA ARROCERA', 'Bimetalico sucio (sonido anormal, no corta calor)', 'Síntoma: la olla emite sonido anormal o no corta el calor al terminar la cocción. Causa probable: bimetalico sucio que no acciona el sistema automático. Acción: limpiar el bimetalico y el mecanismo automático, y regular la llama del piloto.', NULL, 5),
('ARR-06', 'OLLA ARROCERA', 'Manguera de gas mal puesta o estrangulada', 'Síntoma: fuga de gas o falta de encendido en la olla arrocera. Causa probable: manguera de gas mal puesta o estrangulada por contacto con otro equipo. Acción: corregir el tendido de la manguera y ajustar la abrazadera metalica.', NULL, 6),
('ARR-07', 'OLLA ARROCERA', 'Shiglor de piloto en mal estado (llama amarilla)', 'Síntoma: el piloto presenta llama demasiado amarilla con hollin. Causa probable: shiglor de piloto en mal estado que altera la mezcla aire-gas. Acción: reemplazar el shiglor del piloto y calibrar la llama.', NULL, 7),
('ARR-08', 'OLLA ARROCERA', 'Sistema de ignición obstruido por suciedad', 'Síntoma: la olla arrocera no enciende. Causa probable: sistema de ignición (chispero) obstruido por suciedad acumulada. Acción: desmontar y limpiar el sistema de ignición, y realizar pruebas de encendido.', '["REP-086"]', 8),
('EXH-01', 'EXHIBIDOR', 'Empaque de puerta deteriorado', 'Síntoma: el exhibidor pierde temperatura por la puerta. Causa probable: empaque de puerta en mal estado tipo ECASA. Acción: tomar medidas y reemplazar el empaque de puerta correspondiente.', '["REP-090"]', 1),
('EXH-02', 'EXHIBIDOR', 'Foco LED de iluminación quemado', 'Síntoma: la iluminación interna del exhibidor no enciende. Causa probable: foco LED quemado o con falso contacto. Acción: reemplazar el foco LED y verificar el circuito de iluminación.', '["REP-091"]', 2),
('EXH-03', 'EXHIBIDOR', 'Boya (sensor de nivel) de desague defectuosa', 'Síntoma: desbordamiento de agua en la bandeja de drenaje. Causa probable: boya sensor de nivel defectuosa que no corta el llenado. Acción: reemplazar la boya y realizar la conexión al contactor correspondiente.', NULL, 3),
('EXH-04', 'EXHIBIDOR', 'Resistencia de cordon quemada', 'Síntoma: el sistema eléctrico presenta cable de acometida quemado. Causa probable: resistencia de cordon y su cableado quemados por sobrecarga. Acción: reemplazar la resistencia de cordon y el cable de acometida asociado.', NULL, 4),
('EXH-05', 'EXHIBIDOR', 'Control digital descalibrado (corta antes de temperatura)', 'Síntoma: el exhibidor no llega a la temperatura correcta. Causa probable: control full gauge descalibrado que corta el compresor antes de tiempo. Acción: reemplazar el control full gauge y calibrar el set point.', '["REP-092"]', 5),
('APA-01', 'MESA DE APANADO', 'Motor servo no arranca por tarjeta sulfatada', 'Síntoma: el motor de la mesa de apanado no se activa aunque llega voltaje al variador. Causa probable: tarjeta electrónica sulfatada por humedad de harina. Acción: limpiar o reemplazar la tarjeta electrónica y verificar el motor servo.', '["REP-093"]', 1),
('APA-02', 'MESA DE APANADO', 'Tina de la mesa derretida o deformada', 'Síntoma: la tina de la mesa de apanado presenta deformación. Causa probable: exposición a calor excesivo o material de baja resistencia. Acción: reemplazar la tina de la mesa de apanado.', '["REP-094"]', 2),
('APA-03', 'MESA DE APANADO', 'Cepillo de tamiz atorado o desgastado', 'Síntoma: el cepillo de la mesa de apanado se traba durante la operación. Causa probable: acople del cepillo mal colocado o desgastado. Acción: reemplazar el conjunto de cepillos del tamiz y verificar el acople del motor.', NULL, 3),
('APA-04', 'MESA DE APANADO', 'Toma corriente y cable de alimentación dañados', 'Síntoma: la mesa de apanado no enciende. Causa probable: toma corriente y cable de alimentación deteriorados u oxidados. Acción: reemplazar el toma corriente y el cable de alimentación completos.', '["REP-095"]', 4),
('APA-05', 'MESA DE APANADO', 'Caja de transmisión con pinones dañados', 'Síntoma: el motor gira pero no transmite fuerza al cepillo. Causa probable: pinones de la caja de transmisión dañados por desgaste. Acción: reemplazar el motor con su caja de transmisión y realizar pruebas de funcionamiento.', NULL, 5),
('LAV-01', 'LAVAVAJILLAS', 'Presostato de nivel de agua dañado', 'Síntoma: el equipo presenta error de ingreso de agua o fugas por el presostato. Causa probable: presostato de nivel de agua dañado o trampa de aire fisurada. Acción: reemplazar el presostato y la trampa de aire, y probar el ciclo de llenado.', '["REP-096"]', 1),
('LAV-02', 'LAVAVAJILLAS', 'Bomba de desague obstruida o dañada', 'Síntoma: el agua no drena al finalizar el ciclo de lavado. Causa probable: bomba de desague obstruida por residuos o con el eje dañado. Acción: desmontar, limpiar y reemplazar la bomba de desague si no recupera el drenaje.', '["REP-097"]', 2),
('LAV-03', 'LAVAVAJILLAS', 'Resistencia de caldera con cortocircuito', 'Síntoma: la resistencia permanece encendida todo el tiempo. Causa probable: cortocircuito entre cables de la resistencia que dana pistas de la tarjeta. Acción: reemplazar la resistencia de caldera y revisar la tarjeta electrónica asociada.', '["REP-098"]', 3),
('LAV-04', 'LAVAVAJILLAS', 'Fuga de agua por tubería o acoples flojos', 'Síntoma: fuga de agua en la base del lavavajillas. Causa probable: acoples flojos o tubería de 3/8 con perforaciones. Acción: ajustar o reemplazar la tubería y los acoples afectados.', NULL, 4),
('LAV-05', 'LAVAVAJILLAS', 'Probe de temperatura en corto (error 08)', 'Síntoma: el panel muestra error de temperatura con la sonda en corto. Causa probable: probe de temperatura en corto por humedad o desgaste. Acción: verificar el ohmiaje del probe y reemplazarlo si está en corto.', NULL, 5),
('TOS-01', 'TOSTADORA', 'Switch de encendido dañado (recalentado)', 'Síntoma: el switch de encendido se recalienta y el equipo queda conectado en directo. Causa probable: switch de encendido con pines recalentados o quemados. Acción: reemplazar el switch de encendido y el tramo de cable afectado.', '["REP-099"]', 1),
('TOS-02', 'TOSTADORA', 'Cables de alimentación recalentados', 'Síntoma: la tostadora se apaga y enciende de forma intermitente. Causa probable: cables de alimentación recalentados por conexiones flojas. Acción: reemplazar el tramo de cable de alta temperatura y ajustar las conexiones.', NULL, 2),
('TOS-03', 'TOSTADORA', 'Sonda RTD de temperatura dañada', 'Síntoma: la tostadora no controla bien la temperatura de cocción. Causa probable: sonda RTD de temperatura dañada o con lectura erratica. Acción: reemplazar la sonda RTD con cable de 48 pulgadas.', '["REP-100"]', 3),
('TOS-04', 'TOSTADORA', 'Transformador de tarjeta dañado (no enciende)', 'Síntoma: la tostadora no enciende. Causa probable: transformador de la tarjeta de control dañado. Acción: reemplazar el transformador y verificar la alimentación de la tarjeta.', '["REP-101"]', 4),
('TOS-05', 'TOSTADORA', 'Manguera bx de cableado rota (olor a quemado)', 'Síntoma: olor a quemado y cables expuestos junto al equipo. Causa probable: manguera bx de protección del cableado rota por el calor. Acción: reemplazar la manguera bx y el tramo de cable de alta temperatura.', NULL, 5),
('MIC-01', 'MICROONDAS', 'Magnetrón dañado (no calienta)', 'Síntoma: el microondas no calienta el producto. Causa probable: magnetrón fuera de rango de trabajo o con la antena quemada. Acción: reemplazar el magnetrón según el modelo del equipo y probar el calentamiento.', '["REP-102"]', 1),
('MIC-02', 'MICROONDAS', 'Microswitch de puerta dañado', 'Síntoma: el equipo no calienta aunque el transformador entrega voltaje correcto. Causa probable: microswitch de puerta que no ancla correctamente el cierre. Acción: reemplazar el microswitch de puerta y verificar el cierre de seguridad.', '["REP-103"]', 2),
('MIC-03', 'MICROONDAS', 'Estructura interna deteriorada (arcos eléctricos)', 'Síntoma: se generan arcos eléctricos (chispas) dentro de la cavidad. Causa probable: estructura interna del microondas deteriorada por óxido o impacto. Acción: evaluar si la estructura es reparable; si no, dar de baja el equipo.', NULL, 3),
('MIC-04', 'MICROONDAS', 'Fusible quemado (no enciende)', 'Síntoma: el microondas no enciende. Causa probable: fusible de protección quemado por sobrecorriente. Acción: reemplazar el fusible y verificar la causa de la sobrecorriente antes de habilitar el equipo.', NULL, 4),
('GAS-01', 'GAS E INSTALACIONES', 'Fuga de gas en rubinete de equipo de cocción', 'Síntoma: fuga de gas detectada en el rubinete de alimentación de un equipo de cocción. Causa probable: rubinete desgastado que pierde hermeticidad. Acción: reemplazar el rubinete y verificar hermeticidad con agua jabonosa.', '["REP-104"]', 1),
('GAS-02', 'GAS E INSTALACIONES', 'Termostato de termotanque recalentado', 'Síntoma: el termotanque no corta la alimentación de las resistencias por temperatura. Causa probable: termostato recalentado en sus bordes que no censa correctamente. Acción: reemplazar el termostato del termotanque y aislar las conexiones.', '["REP-105"]', 2),
('GAS-03', 'GAS E INSTALACIONES', 'Botonera de montacargas rota', 'Síntoma: el montacargas no responde a los mandos. Causa probable: botonera de control rota o con botón de emergencia salido. Acción: reemplazar la botonera y su caja de protección metalica.', NULL, 3),
('GAS-04', 'GAS E INSTALACIONES', 'Final de carrera dañado en montacargas', 'Síntoma: el montacargas presenta fallas al subir o bajar a un nivel determinado. Causa probable: final de carrera dañado con falsos contactos. Acción: reemplazar el final de carrera afectado y probar el recorrido completo.', NULL, 4),
('GAS-05', 'GAS E INSTALACIONES', 'Válvula de alivio activada por presión de agua', 'Síntoma: activación de la válvula de alivio del termotanque. Causa probable: acumulación de presión de agua por termostato que no corta la resistencia a tiempo. Acción: revisar el termostato, corregir la falla y verificar la válvula de alivio.', '["REP-105"]', 5),
('DIS-01', 'DISPENSADOR DE BEBIDAS', 'Display no enciende (falla de alimentación al tablero)', 'Síntoma: el display del dispensador no enciende. Causa probable: falla de alimentación al tablero de control. Acción: verificar el voltaje de entrada al tablero y reemplazar el conjunto de tablero de control si no recupera encendido.', '["REP-106"]', 1),
('DIS-02', 'DISPENSADOR DE BEBIDAS', 'Tablero de control no envia señales de funcionamiento', 'Síntoma: el equipo no manda las señales necesarias para funcionar aunque el display intenta encender. Causa probable: falla interna del tablero de control. Acción: revisar las conexiones internas y reemplazar el tablero de control.', '["REP-106"]', 2),
('DIS-03', 'DISPENSADOR DE BEBIDAS', 'Falla recurrente de tablero de control', 'Síntoma: el equipo repite la misma falla de encendido tras una intervención previa. Causa probable: tablero de control con daño recurrente no resuelto en la intervención anterior. Acción: reemplazar el tablero de control completo en lugar de repararlo.', '["REP-106"]', 3),
('DIS-04', 'DISPENSADOR DE BEBIDAS', 'Protector o dispensador de jabon mal instalado', 'Síntoma: el protector del dispensador de jabon no queda fijo en su lugar. Causa probable: instalación incompleta del dispensador o su protector. Acción: instalar correctamente el dispensador de jabon y su protector, y verificar la sujeción.', NULL, 4),
('CAM-01', 'CAMPANA', 'Protector térmico activado o dañado (no enciende)', 'Síntoma: la campana no enciende. Causa probable: protector térmico del motor activado o en corto, impidiendo el accionamiento de la bobina. Acción: verificar el protector térmico, corregir la conexión y reemplazarlo si no acciona correctamente.', NULL, 1),
('CAM-02', 'CAMPANA', 'Switch de encendido con falso contacto', 'Síntoma: falso contacto al accionar el switch de encendido de la campana. Causa probable: contactos del switch desgastados o sucios. Acción: limpiar o reemplazar el switch de encendido y verificar el circuito de control.', NULL, 2),
('CAM-03', 'CAMPANA', 'Cable de alimentación o reflector con aislamiento dañado', 'Síntoma: descarga a tierra al tocar la estructura de la campana. Causa probable: aislamiento del cable de reflector, timer o alimentación deteriorado. Acción: reemplazar el tramo de cable dañado, aislar conexiones y cambiar capuchones.', NULL, 3),
('CAM-04', 'CAMPANA', 'Lampara o reflector de iluminación quemado', 'Síntoma: la campana no ilumina la zona de cocción. Causa probable: lampara o reflector quemado por el calor y el uso continuo. Acción: reemplazar la lampara y/o el reflector, y verificar el circuito de iluminación.', '["REP-107", "REP-108"]', 4),
('BAT-01', 'BATIDORA', 'Falla en tarjeta de control (display sin información)', 'Síntoma: el display no muestra la temperatura ni la información de programación. Causa probable: falla o suciedad en la tarjeta electrónica de control. Acción: limpiar la tarjeta, conectores y terminales; reemplazar el conjunto de placa de control si no recupera.', '["REP-109"]', 1),
('BAT-02', 'BATIDORA', 'Engranajes de caja de transmisión desgastados', 'Síntoma: ruido o perdida de fuerza en el mecanismo de batido. Causa probable: desgaste de los engranajes de la caja de transmisión por falta de lubricación. Acción: lubricar o reemplazar los engranajes de la caja de transmisión y realizar pruebas de funcionamiento.', NULL, 2),
('BAT-03', 'BATIDORA', 'Carbones de motor desgastados', 'Síntoma: el motor pierde fuerza o presenta chispeo interno. Causa probable: carbones de motor desgastados por uso prolongado. Acción: revisar el estado de los carbones y reemplazarlos si están por debajo de la longitud mínima.', NULL, 3),
('BAT-04', 'BATIDORA', 'Rodamientos secos o desgastados (ruido en el eje)', 'Síntoma: ruido en el eje de batido durante la operación. Causa probable: rodamientos secos o desgastados por falta de lubricación periodica. Acción: lubricar los rodamientos y reemplazarlos si presentan juego excesivo.', NULL, 4)
